class Component extends DCLogic {
  constructor(props) { super(props); this.state = { tab: null, open: { r: true }, card: null, hl: '', compose: false, cText: '', cErr: false, note: '', actOpen: false, lvlOpen: false, m: '', invited: [], iName: '', iMail: '', iErr: false, iDone: false, view: '' }; }

  componentDidMount() { this._esc = (e) => { if (e.key !== 'Escape') return; if (this.state.m) this.closeM(); else this.setState({ card: '' }); }; document.addEventListener('keydown', this._esc); }
  componentWillUnmount() { document.removeEventListener('keydown', this._esc); clearTimeout(this._tt); }
  openCard(id) { this.setState({ card: id, compose: false, cText: '', cErr: false, note: '' }); }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state, ok = (v) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.trim());
    const mob = true;
    const tab = S.tab ?? 'over';
    const T0 = [['over', 'Обзор'], ['map', 'Карта сети'], ['cl', 'Клиенты сети']];
    const tabs = T0.map(([k, t]) => ({ t, sel: tab === k ? 'true' : 'false', pick: () => this.setState({ tab: k, open: {}, hl: '' }) }));
    const ST = { ok: ['badge--ok', 'Работает'], warn: ['badge--warn', 'Давно не заходил'], wait: ['badge--muted', 'Ждёт первого клиента'], reg: ['badge--muted', 'Приглашён, ещё не зашёл'] };
    const PT = { m: ['badge--ok', 'Суперактивный'], e: ['badge--ok', 'Активный'], s: ['badge--muted', 'Средний'], r: ['badge--warn', 'Давно не заходил'], t: ['badge--warn', 'Давно не заходил'] };

    /* сеть: [id, ФИО, коротко, кто пригласил, уровень, состояние, подпись состояния] */
    const RAW = HB.net.raw();
    const T = RAW.map((r) => [r[0], r[1], r[3], r[4], r[5]]).concat(S.invited.map((x) => [x.id, x.name, '', 1, 'reg']));
    const kidsOf = (id) => T.filter((x) => x[2] === id);
    const descN = (id) => kidsOf(id).reduce((a, x) => a + 1 + descN(x[0]), 0);

    /* первый уровень: [почта, телефон, подсказка, вошёл, был, действие] */
    const F = HB.net.F;
    const mkRow = (x) => {
      const f = F[x[0]], reg = x[4] === 'reg', st = PT[x[0]] || ST[x[4]], id = x[0];
      return {
        id, name: x[1], badge: st[0], tag: st[1], click: !reg, noclick: reg,
        since: reg ? 'Приглашение отправлено сегодня' : f[3], lastIn: reg ? '' : f[4],
        hint: reg ? 'Как только человек зарегистрируется, он встанет в Вашу сеть.' : f[2],
        open: () => this.openCard(id)
      };
    };
    const firstRows = T.filter((x) => x[3] === 1).map(mkRow);

    const BD = { ok: 'badge--ok', warn: 'badge--warn', wait: 'badge--muted' };
    const by = {};
    RAW.forEach((r) => { by[r[0]] = { id: r[0], name: r[1], short: r[2], par: r[3], lvl: r[4], st: r[5], tag: (PT[r[0]] || [0, r[6]])[1], badge: (PT[r[0]] || [BD[r[5]]])[0], l1: r[4] === 1, ini: r[1].split(' ').map((w) => w[0]).join('') }; });
    const N = RAW.map((r) => by[r[0]]);
    N.forEach((n) => { n.br = n.par ? by[n.par].br : n.id; n.byS = n.par ? by[n.par].short : 'Вы'; n.bcls = 'b-' + n.br; n.nol1 = !n.l1; n.open = n.l1 ? () => this.openCard(n.id) : () => {}; n.aria = (n.l1 ? 'Партнёр первого уровня: ' + n.name + ', ' + n.tag + '. Открыть карточку, чтобы написать' : n.lvl + '-й уровень: ' + n.name + ', ' + n.tag + '. Пригласил: ' + n.byS); });
    const kids = (id) => N.filter((x) => x.par === id);
    const L1 = N.filter((n) => n.l1);
    const lvN = [0, 0, 0, 0, 0, 0]; N.forEach((n) => { lvN[n.lvl]++; });
    const sumRows = [1, 2, 3, 4, 5].map((k) => ({ n: lvN[k], t: k + '-й уровень' })).concat([{ n: N.length, t: 'Всего в сети' }]);
    const ru = (n, a, b, c) => { const m = n % 100, d = n % 10; return (m > 10 && m < 15) ? c : d === 1 ? a : (d > 1 && d < 5) ? b : c; };
    const ring = this.mapVals({ N, L1, kids, descN: (id) => descN(id), ru, mob }, S.view || (mob ? 'list' : 'rings'));

    const SG = { w: ['badge--ok', 'В работе по стране'], h: ['badge--done', 'Потенциальная покупка'], c: ['badge--ok', 'Квалификация'], n: ['badge--ok', 'Новая'], d: ['badge--done', 'Бронь'], x: ['badge--muted', 'Покупка отложена'] };
    const NC = [
      ['Георгий М.', 'Дубай', 'w', 'Марат Сулейманов, 1-й уровень', '6 ноября'],
      ['Лариса Т.', 'Анталья', 'h', 'Марат Сулейманов, 1-й уровень', '4 ноября'],
      ['Антон К.', 'Лимассол', 'd', 'Марат Сулейманов, 1-й уровень', '29 октября'],
      ['Виктория Ш.', 'Тбилиси', 'c', 'Елена Воронцова, 1-й уровень', '5 ноября'],
      ['Дарья Н.', 'Дубай', 'n', 'Айгуль Нурлан, 2-й уровень', '6 ноября'],
      ['Сергей П.', 'Анталья', 'w', 'Павел Крылов, 2-й уровень', '3 ноября'],
      ['Олег Ч.', 'Лимассол', 'h', 'Денис Павлов, 3-й уровень', '2 ноября'],
      ['Мария Б.', 'Дубай', 'x', 'Денис Павлов, 3-й уровень', '1 ноября'],
      ['Игорь Л.', 'Лимассол', 'c', 'Тимур Алиев, 1-й уровень', '28 октября']
    ];
    const clRows = NC.map((c) => ({ name: c[0], badge: SG[c[2]][0], tag: SG[c[2]][1], sub: c[1] + '. Передал: ' + c[3] + '. Обновлено ' + c[4] + '.' }));

    /* карточка агента */
    const cid = S.card === null ? (this.props.card ?? '') : S.card;
    const CD = {
      m: { mail: F.m[0], phone: F.m[1], closed: 1, income: '4 200', who: 'Марат Сулейманов', ev: [
        ['6 ноября', [['Передал клиента: Георгий М.', 'Дубай', 'iSend']]],
        ['5 ноября', [['Последний вход в кабинет', '', 'iLogin']]],
        ['29 октября', [['Клиент Антон К. внёс первый платёж', 'Лимассол', 'iCheck']]],
        ['14 июня', [['Пришёл в сеть по Вашему приглашению', '', 'iUser']]]] },
      e: { mail: F.e[0], phone: F.e[1], closed: 0, income: '0', who: 'Елена Воронцова', ev: [
        ['5 ноября', [['Передал клиента: Виктория Ш.', 'Тбилиси', 'iSend']]],
        ['3 ноября', [['Последний вход в кабинет', '', 'iLogin']]],
        ['2 августа', [['Пришла в сеть по Вашему приглашению', '', 'iUser']]]] },
      r: { mail: F.r[0], phone: F.r[1], closed: 0, income: '0', who: 'Роман Гусев', ev: [
        ['22 сентября', [['Последний вход в кабинет', '', 'iLogin'], ['Пришёл в сеть по Вашему приглашению', '', 'iUser']]]] },
      t: { mail: F.t[0], phone: F.t[1], closed: 0, income: '0', who: 'Тимур Алиев', ev: [
        ['28 октября', [['Передал клиента: Игорь Л.', 'Лимассол', 'iSend']]],
        ['9 октября', [['Последний вход в кабинет', '', 'iLogin'], ['Пришёл в сеть по Вашему приглашению', '', 'iUser']]]] },
      s: { mail: F.s[0], phone: F.s[1], closed: 0, income: '0', who: 'Софья Лебедева', ev: [
        ['4 ноября', [['Последний вход в кабинет', '', 'iLogin'], ['Пришла в сеть по Вашему приглашению', '', 'iUser']]]] }
    };
    const CHIPS = ['Чем помочь с первым клиентом?', 'Чего не хватает для работы?', 'Как дела с клиентами?'];
    let card = {}, cardOpen = false;
    if (cid && CD[cid]) {
      cardOpen = true;
      const x = T.find((y) => y[0] === cid), f = F[cid], d = CD[cid], st = PT[cid];
      const cl = NC.filter((c) => c[3].indexOf(d.who) === 0).slice(0, 3).map((c) => ({ name: c[0], place: c[1], badge: SG[c[2]][0], tag: SG[c[2]][1] }));
      const days = d.ev.map((g) => ({ day: g[0], items: g[1].map((v) => ({ title: v[0], hasNote: !!v[1], note: v[1], iUser: v[2] === 'iUser', iSend: v[2] === 'iSend', iCheck: v[2] === 'iCheck', iLogin: v[2] === 'iLogin' })) }));
      const nEv = d.ev.reduce((a, g) => a + g[1].length, 0), nKids = descN(cid), cE = S.cErr && !S.cText.trim();
      card = {
        name: x[1], badge: st[0], tag: st[1], tone: x[4] === 'warn' ? 'err' : 'ok', warn: x[4] === 'warn', good: x[4] !== 'warn', hint: f[2],
        since: f[3], lastIn: f[4].replace('вход ', ''), mail: d.mail, phone: d.phone, note: S.note,
        passed: String(cl.length), closed: String(d.closed), income: d.income, kids: String(nKids), hasKids: nKids > 0,
        hasCl: cl.length > 0, cl, days, evCount: nEv + ' ' + (nEv === 1 ? 'событие' : nEv < 5 ? 'события' : 'событий'),
        close: () => this.setState({ card: '' }),
        toMap: () => this.setState({ card: '', tab: 'map', hl: cid }),
        copy: () => this.setState({ note: 'Телефон скопирован' }),
        tel: 'tel:+' + d.phone.replace(/\D/g, ''), sent: S.note.indexOf('Сообщение отправлено') === 0, openChat: () => { HB.net.openChat(cid); window.location.href = 'soobshcheniya-chat.html'; },
        write: () => this.setState({ compose: !S.compose, note: '' }),
        compose: S.compose, chips: CHIPS.map((t) => ({ t, pick: () => this.setState({ cText: t, cErr: false }) })),
        cText: S.cText, cSet: (e) => this.setState({ cText: e.target.value, cErr: false }), cErr: cE ? 'is-err' : '', cErr_e: cE ? 'Напишите сообщение или выберите фразу' : '',
        cSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.cText.trim()) { this.setState({ cErr: true }); return; } HB.net.send(cid, S.cText.trim()); this.setState({ compose: false, cText: '', note: 'Сообщение отправлено: ' + x[1] + '. Оно в «Сообщениях».' }); },
        cCancel: () => this.setState({ compose: false, cText: '', cErr: false })
      };
    }

    const e1 = S.iErr && !S.iName.trim() ? 'is-err' : '', e2 = S.iErr && !ok(S.iMail) ? 'is-err' : '';
    return Object.assign(this.baseVals(), { lang: 'ru', copy: (e) => { try { navigator.clipboard.writeText('housebook.global/join?ref=PRG7K2'); } catch (x) {} this.say('Ссылка скопирована', e); }, sayWa: (e) => this.say('В кабинете откроется WhatsApp со ссылкой', e), sayTg: (e) => this.say('В кабинете откроется Telegram со ссылкой', e), sayMail: (e) => this.say('В кабинете откроется письмо со ссылкой', e),
      openShare: (e) => this.openM('share', e), openQr: (e) => this.openM('qr', e), dlQr: (e) => this.say('QR-код сохранён', e), m_share: S.m === 'share', m_qr: S.m === 'qr',
      cardOpen, card, tabs, tOver: tab === 'over', tMap: tab === 'map', tCl: tab === 'cl',
      firstN: firstRows.length, netN: N.length, activeN: N.filter((x) => x.st === 'ok').length,
      actOpen: S.actOpen, actToggle: () => this.setState({ actOpen: !S.actOpen }), lvlOpen: S.lvlOpen, lvlToggle: () => this.setState({ lvlOpen: !S.lvlOpen }),
      firstRows, sumRows, hlOn: !!S.hl, hlCls: S.hl ? 'hl-b-' + S.hl : '', hlName: S.hl ? (by[S.hl] || {}).name : '', hlOff: () => this.setState({ hl: '' }), ...ring,
      clN: NC.length, clWork: NC.filter((c) => c[2] !== 'x' && c[2] !== 'd').length, clDone: NC.filter((c) => c[2] === 'd').length, clRows,
      invOpen: (e) => this.openM('inv', e, { iDone: false, iErr: false, iName: '', iMail: '' }),
      m_inv: S.m === 'inv', iForm: !S.iDone, iDone: S.iDone,
      iName: S.iName, iMail: S.iMail, iSetName: (e) => this.setState({ iName: e.target.value, iErr: false }), iSetMail: (e) => this.setState({ iMail: e.target.value, iErr: false }),
      iNameErr: e1, iNameErr_e: e1 ? 'Напишите имя' : '', iMailErr: e2, iMailErr_e: e2 ? 'Проверьте почту: нужен адрес вида name@example.com' : '',
      iSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.iName.trim() || !ok(S.iMail)) { this.setState({ iErr: true }); return; } this.setState({ iDone: true, invited: S.invited.concat([{ id: 'n' + (S.invited.length + 1), name: S.iName.trim(), mail: S.iMail.trim(), ts: Date.now() }]) }); },
      iToNet: () => this.setState({ m: '', tab: 'over', open: {} }),
    });
  }


  mapVals(c, view) {
    const { N, L1, descN, kids } = c;
    const MOB = !!c.mob;
    const R = [0.2, 0.275, 0.34, 0.395, 0.445];                       /* радиусы колец, доля ширины схемы */
    const MAXS = MOB ? [6.2, 5.6, 5.4, 5.2, 5.0] : [4.2, 3.8, 3.6, 3.4, 3.2]; const INI_MIN = MOB ? 5.0 : 3.0;   /* наибольший диаметр точки, cqw */
    const MINS = MOB ? 2.5 : 1.9, GAPC = MOB ? 0.4 : 0.4, FILL = 0.8, TOPG = 14, GAPD = 1.2;
    const f = (v) => v.toFixed(2);
    const sorted = L1.slice().sort((a, b) => descN(b.id) - descN(a.id));
    const kc = {}; sorted.forEach((b, i) => { kc[b.id] = i < 5 ? 'k' + (i + 1) : 'kg'; });
    const cls = (n) => kc[n.br] + ' ' + n.bcls;
    /* сектора: ширина пропорциональна числу людей; у каждого партнёра не меньше угла под свою точку первого уровня */
    const circ = (k) => 2 * Math.PI * R[k - 1] * 100;
    const s1 = Math.min(MAXS[0], FILL * circ(1) / L1.length);
    const minA = (s1 + GAPC) / (R[0] * 100) * 180 / Math.PI + GAPD;
    const wt = sorted.map((b) => descN(b.id) + 1), avail = 360 - TOPG;
    const span = wt.map(() => 0), fixed = wt.map(() => false);
    for (let it = 0; it < 20; it++) {
      const free = wt.reduce((a, w, i) => a + (fixed[i] ? 0 : w), 0), left = avail - span.reduce((a, s, i) => a + (fixed[i] ? s : 0), 0);
      let ch = false; wt.forEach((w, i) => { if (!fixed[i]) { span[i] = left * w / free; if (span[i] < minA) { span[i] = minA; fixed[i] = true; ch = true; } } });
      if (!ch) break;
    }
    const ang = {}, wedges = [];
    let a0 = -90 + TOPG / 2;
    sorted.forEach((b, i) => {
      const nl0 = (id) => { const ks = kids(id); return ks.length ? ks.reduce((a, x) => a + nl0(x.id), 0) : 1; };
      const nl = nl0(b.id); let li = 0;
      const place = (n) => { const ks = kids(n.id); if (!ks.length) { ang[n.id] = a0 + (li++ + 0.5) * span[i] / nl; return; } ks.forEach(place); ang[n.id] = (ang[ks[0].id] + ang[ks[ks.length - 1].id]) / 2; };
      place(b); ang[b.id] = a0 + span[i] / 2; /* точка партнёра по центру его сектора */
      if (descN(b.id) > 0) wedges.push({ bcls: cls(b), sty: 'background:conic-gradient(from ' + f(a0 + 90 + GAPD / 2) + 'deg,color-mix(in srgb,var(--bc) ' + (kc[b.id] === 'kg' ? (i % 2 ? 8 : 16) : 14) + '%,var(--hb-paper)) 0 ' + f(span[i] - GAPD) + 'deg,transparent ' + f(span[i] - GAPD) + 'deg);width:100%;height:100%;-webkit-mask-image:radial-gradient(farthest-side,#000 ' + f((R[4] + 0.03) * 200) + '%,transparent ' + f((R[4] + 0.03) * 200) + '%);mask-image:radial-gradient(farthest-side,#000 ' + f((R[4] + 0.03) * 200) + '%,transparent ' + f((R[4] + 0.03) * 200) + '%)' });
      a0 += span[i];
    });
    /* кольца: размер точки по числу людей на кольце, раздвигание соседей, плотная полоса, если не помещается */
    const size = {}, dense = [], pos = {}, sizeK = [];
    const stats = [];
    for (let k = 1; k <= 5; k++) {
      const mem = N.filter((n) => n.lvl === k).sort((a, b) => ang[a.id] - ang[b.id]);
      const r100 = R[k - 1] * 100, n = mem.length;
      if (n * (MINS + GAPC) > FILL * circ(k)) { dense[k] = true; sizeK[k] = 0; stats.push({ k, n, dense: true }); mem.forEach((m) => { pos[m.id] = { a: ang[m.id], r: R[k - 1] }; }); continue; }
      let s = Math.min(MAXS[k - 1], FILL * circ(k) / n), A = mem.map((m) => ang[m.id]), tgt = A.slice(), ok = false;
      for (; s >= MINS - 1e-9 && !ok; s -= 0.1) {
        const gap = (s + GAPC) / r100 * 180 / Math.PI; A = tgt.slice();
        for (let it = 0; it < 400; it++) {
          let mv = false;
          for (let i = 0; i < n; i++) { const j = (i + 1) % n; let d = A[j] - A[i]; if (j === 0) d += 360; if (d < gap - 1e-3) { const e = (gap - d) / 2; A[i] -= e; A[j] += e; mv = true; } }
          if (!mv) break;
        }
        ok = true; for (let i = 0; i < n; i++) { const j = (i + 1) % n; let d = A[j] - A[i]; if (j === 0) d += 360; if (d < gap - 0.05) ok = false; }
      }
      s += 0.1;
      if (!ok) { dense[k] = true; sizeK[k] = 0; stats.push({ k, n, dense: true }); mem.forEach((m) => { pos[m.id] = { a: ang[m.id], r: R[k - 1] }; }); continue; }
      sizeK[k] = s; let md = 0; mem.forEach((m, i) => { pos[m.id] = { a: A[i], r: R[k - 1] }; md = Math.max(md, Math.abs(A[i] - tgt[i])); });
      stats.push({ k, n, s: +s.toFixed(2), maxShift: +md.toFixed(1) });
    }
    this._stats = stats; if (typeof window !== 'undefined') window.__ringStats = stats;
    N.forEach((n) => { const p = pos[n.id], a = p.a * Math.PI / 180; p.x = 50 + p.r * 100 * Math.cos(a); p.y = 50 + p.r * 100 * Math.sin(a); });
    const rings = [1, 2, 3, 4, 5].map((k) => ({ sty: 'left:50%;top:50%;width:' + f(R[k - 1] * 200) + '%;height:' + f(R[k - 1] * 200) + '%' }));
    const rls = [1, 2, 3, 4, 5].map((k) => ({ t: String(k), sty: 'left:50%;top:' + f(50 - R[k - 1] * 100) + '%' }));
    const spokes = [];
    N.forEach((n) => { if (dense[n.lvl] || (n.par && dense[n.lvl - 1])) return; const p = n.par ? pos[n.par] : { x: 50, y: 50 }, q = pos[n.id]; const dx = q.x - p.x, dy = q.y - p.y; spokes.push({ cls: cls(n), sty: 'left:' + f(p.x) + '%;top:' + f(p.y) + '%;width:' + f(Math.hypot(dx, dy)) + 'cqw;transform:rotate(' + f(Math.atan2(dy, dx) * 180 / Math.PI) + 'deg)' }); });
    const tp = (p) => (p.x > 62 ? 'tl' : p.x < 38 ? 'tr' : '') + (p.y < 24 ? ' bl' : '');
    const dots = N.filter((n) => !dense[n.lvl]).sort((a, b) => b.lvl - a.lvl).map((n) => { const p = pos[n.id], s = sizeK[n.lvl];
      return { l1: n.l1, nol1: n.nol1, bcls: cls(n) + (s >= INI_MIN ? '' : ' sm'), ini: s >= INI_MIN ? n.ini : '', name: n.name, sub: n.lvl === 1 ? '1-й уровень, ' + n.tag + '. В ветке ' + (descN(n.id) + 1) : n.lvl + '-й уровень, ' + n.tag + '. Пригласил: ' + n.byS, open: n.open, aria: n.aria, tp: tp(p),
